begin; do $$ declare test_id uuid; affected int; initial_time timestamptz; begin insert into public.naver_blog_seo_drafts(user_id,topic,strategy,title,body,status,extension_handoff_at) values('4a82ff77-97f7-474d-866e-8e9431858ed3','자동 발행 합성 회귀','C-Rank 기본','자동 발행 합성 회귀','실제 생성·발행하지 않는 트랜잭션 내부 합성 원고입니다.','ready',now()) returning id,created_at into test_id,initial_time; update public.naver_blog_seo_drafts set seo_report='{"saveRevision":"one","autoPublish":{"runId":"run-one","state":"writing"}}'::jsonb where id=test_id and user_id='4a82ff77-97f7-474d-866e-8e9431858ed3' and seo_report->>'saveRevision' is null and seo_report->'autoPublish'->>'runId' is null; get diagnostics affected=row_count; assert affected=1,'initial claim'; update public.naver_blog_seo_drafts set title='must not change' where id=test_id and seo_report->>'saveRevision' is null and seo_report->'autoPublish'->>'runId' is null; get diagnostics affected=row_count; assert affected=0,'stale concurrent write denied'; update public.naver_blog_seo_drafts set title='must not change' where id=test_id and user_id='00000000-0000-0000-0000-000000000001'; get diagnostics affected=row_count; assert affected=0,'foreign owner denied'; update public.naver_blog_seo_drafts set seo_report=jsonb_set(seo_report,'{autoPublish,state}','"publishing"') where id=test_id and seo_report->'autoPublish'->>'runId'='run-one' and seo_report->'autoPublish'->>'state'='writing'; get diagnostics affected=row_count; assert affected=1,'arm CAS'; update public.naver_blog_seo_drafts set seo_report='{}' where id=test_id and seo_report->'autoPublish'->>'state'='writing'; get diagnostics affected=row_count; assert affected=0,'repeat arm denied'; assert (select created_at=initial_time from public.naver_blog_seo_drafts where id=test_id),'original lifespan preserved'; end $$; rollback;
